from dataclasses import dataclass, field
from typing import List
from datetime import date

@dataclass
class Book:
    isbn: str
    title: str
    author: str
    available: bool = True

    def mark_borrowed(self) -> None:
        self.available = False

class Member:
    def __init__(self, member_id: int, name: str, email: str):
        self.member_id = member_id
        self.name = name
        self.email = email
        self._loans: List[Loan] = []

    def borrow(self, book: Book) -> Loan:
        if not book.available:
            raise ValueError("book not available")
        book.mark_borrowed()
        loan = Loan(len(self._loans) + 1, book, self, date.today())
        self._loans.append(loan)
        return loan

class Loan:
    def __init__(self, loan_id: int, book: Book, member: Member, start: date):
        self.loan_id = loan_id
        self.book = book
        self.member = member
        self.start = start

    def is_overdue(self, today: date) -> bool:
        return (today - self.start).days > 14

class Person:
    def __init__(self, name: str, birth_year: int):
        self.name = name
        self.birth_year = birth_year

    def age(self, current_year: int) -> int:
        return current_year - self.birth_year

class Student(Person):
    def __init__(self, name: str, birth_year: int, student_id: str):
        super().__init__(name, birth_year)
        self.student_id = student_id
        self.enrollments: list[Enrollment] = []

    def enroll(self, course: Course) -> Enrollment:
        enrollment = Enrollment(self, course)
        self.enrollments.append(enrollment)
        return enrollment

class Course:
    def __init__(self, code: str, title: str, credits: int):
        self.code = code
        self.title = title
        self.credits = credits

class Enrollment:
    def __init__(self, student: Student, course: Course):
        self.student = student
        self.course = course
        self.grade: str | None = None

from abc import ABC, abstractmethod
from typing import Protocol

class Notifier(ABC):
    @abstractmethod
    def send(self, recipient: str, message: str) -> bool:
        ...

class EmailNotifier(Notifier):
    def __init__(self, smtp_host: str):
        self.smtp_host = smtp_host

    def send(self, recipient: str, message: str) -> bool:
        print(f"EMAIL to {recipient}: {message}")
        return True

class SmsNotifier(Notifier):
    def __init__(self, gateway_url: str):
        self.gateway_url = gateway_url

    def send(self, recipient: str, message: str) -> bool:
        print(f"SMS to {recipient}: {message}")
        return True

class AlertService:
    def __init__(self, notifier: Notifier):
        self.notifier = notifier

    def broadcast(self, users: list[str], message: str) -> int:
        sent = 0
        for user in users:
            if self.notifier.send(user, message):
                sent += 1
        return sent

class Warehouse:
    def __init__(self, location: str, capacity: int):
        self.location = location
        self.capacity = capacity
        self.inventory: dict[str, int] = {}

    def stock(self, sku: str, quantity: int) -> None:
        self.inventory[sku] = self.inventory.get(sku, 0) + quantity

class Shipment:
    def __init__(self, shipment_id: str, warehouse: Warehouse):
        self.shipment_id = shipment_id
        self.warehouse = warehouse
        self.items: list[tuple[str, int]] = []

    def add_item(self, sku: str, quantity: int) -> None:
        self.items.append((sku, quantity))
        self.warehouse.stock(sku, -quantity)

class Carrier:
    def __init__(self, name: str, tracking_prefix: str):
        self.name = name
        self.tracking_prefix = tracking_prefix

    def dispatch(self, shipment: Shipment) -> str:
        return f"{self.tracking_prefix}-{shipment.shipment_id}"

