class PricingEngine:
    def __init__(self, tax_rate: float):
        self.tax_rate = tax_rate

    def price_with_tax(self, base_price: float) -> float:
        return base_price * (1 + self.tax_rate)

class CheckoutService:
    def __init__(self, catalog: CatalogRepository, pricing: PricingEngine):
        self.catalog = catalog
        self.pricing = pricing

    def quote(self, sku: str) -> float:
        product = self.catalog.find_by_sku(sku)
        if not product:
            return 0.0
        return self.pricing.price_with_tax(product["price"])

