typedef struct Account {
    int account_id;
    char owner_name[64];
    double balance;
} Account;

typedef struct Transaction {
    int transaction_id;
    Account* source;
    Account* destination;
    double amount;
    char memo[64];
} Transaction;

void transaction_execute(Transaction* txn) {
    if (txn && txn->source && txn->destination) {
        txn->source->balance -= txn->amount;
        txn->destination->balance += txn->amount;
    }
}
